class.description:
[NetwEntity], [NetwTableHandle] and your own code save and load their state through a [NetwDatabase]. A [NetwDatabaseBackend] does the actual storage.
A record is a [Dictionary] stored under a [StringName] id. Its [NetwSchema] is the table definition and the record is a row in it.
Await [method open] before reading or writing.
[codeblock]
func _ready() -> void:
    Netw.configure_database(self, &"saves").backend(preload("res://filesystem_backend.tres"))

func start_game(slot: StringName) -> void:
    var db: NetwDatabase = Netw.database(self, &"saves")
    var error: Error = await db.open(slot).wait()
    if error != OK:
        show_load_error(error)
        return
    enter_game()
[/codeblock]
